    if (buffer[dwRead - 1] != '\0') {
        LogError("Data is not NULL-terminated");
        HeapFree(buffer);
        return FALSE;
    }

    // Parse the data into STARTUP_DATA
    char* token = strtok(buffer, "\0");
    if (token == NULL) {
        LogError("No working directory found in the data");
        HeapFree(buffer);
        return FALSE;
    }
    sud->workingDirectory = token;

    token = strtok(NULL, "\0");
    if (token == NULL) {
        LogError("No command line found in the data");
        HeapFree(buffer);
        return FALSE;
    }
    sud->commandLine = token;

    token = strtok(NULL, "\0");
    if (token == NULL) {
        LogError("No standard input found in the data");
        HeapFree(buffer);
        return FALSE;
    }
    sud->standardInput = token;

    bResult = TRUE;
    return bResult;
}

#include <windows.h>
