#include <string.h>

#define LOG_ERROR(fmt, ...) fprintf(stderr, "ERROR: " fmt "\n", __VA_ARGS__)

BOOL GetStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD dwRead;
    DWORD dwTotalBytesAvail;
    DWORD dwReadSize;
    DWORD dwPeekSize;
    LPVOID pBuffer = NULL;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &dwTotalBytesAvail, NULL)) {
        LOG_ERROR("PeekNamedPipe failed with error %lu", GetLastError());
        return FALSE;
    }

    if (dwTotalBytesAvail == 0) {
        LOG_ERROR("No data available in pipe");
        return FALSE;
    }

    pBuffer = malloc(dwTotalBytesAvail);
    if (!pBuffer) {
        LOG_ERROR("Memory allocation failed");
        return FALSE;
    }

    if (!ReadFile(pipe, pBuffer, dwTotalBytesAvail, &dwRead, NULL)) {
        LOG_ERROR("ReadFile failed with error %lu", GetLastError());
        free(pBuffer);
        return FALSE;
    }

    if (dwRead != dwTotalBytesAvail) {
        LOG_ERROR("Incomplete read from pipe");
        free(pBuffer);
        return FALSE;
    }

    char* data = (char*)pBuffer;
    if (!data || !data[dwRead - 1]) {
        LOG_ERROR("Received data is not NULL-terminated");
        free(pBuffer);
        return FALSE;
    }

    sud->workingDirectory = _strdup(data);
    if (!sud->workingDirectory) {
        LOG_ERROR("Failed to allocate memory for working directory");
        free(pBuffer);
        return FALSE;
    }

    char* optionsStart = strchr(data, '\0');
    if (!optionsStart) {
        LOG_ERROR("No NULL separator found in data");
        free(pBuffer);
        free(sud->workingDirectory);
        return FALSE;
    }
    optionsStart += 1;
    sud->commandLineOptions = _strdup(optionsStart);
    if (!sud->commandLineOptions) {
        LOG_ERROR("Failed to allocate memory for command line options");
        free(pBuffer);
        free(sud->workingDirectory);
        return FALSE;
    }

    char* stdinStart = strchr(optionsStart, '\0');
    if (!stdinStart) {
        LOG_ERROR("No NULL separator found for stdin");
        free(pBuffer);
        free(sud->workingDirectory);
        free(sud->commandLineOptions);
        return FALSE;
    }
    stdinStart += 1;
    sud->standardInput = _strdup(stdinStart);
    if (!sud->standardInput) {
        LOG_ERROR("Failed to allocate memory for standard input");
        free(pBuffer);
        free(sud->workingDirectory);
        free(sud->commandLineOptions);
        return FALSE;
    }

    // Ensure the string is NULL-terminated
    if (!sud->standardInput[strlen(sud->standardInput) - 1]) {
        LOG_ERROR("Standard input data is not NULL-terminated");
        free(pBuffer);
        free(sud->workingDirectory);
        free(sud->commandLineOptions);
        free(sud->standardInput);
        return FALSE;
    }

    free(pBuffer);
    return TRUE;
}

